    #[arg(help = "Optional expression string to run eva in command mode")]
    input: Option<String>,

    #[arg(short, long, default_value = "10", help = "Number of decimal places in output (1 - 64)")]
    fix: usize,

    #[arg(short, long, default_value = "10", help = "Radix of calculation output (1 - 36)")]
    base: u32,

    #[arg(short, long, default_value = "degree", help = "Angle unit", value_enum)]
    angle_unit: AngleUnit,
}

#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum, Debug)]
#[allow(non_camel_case_types)]
enum AngleUnit {
    degree,
    radian,
    gradian,
}

fn main() {
    let cli = Cli::parse();

    let mut editor = Editor::<()>::new().unwrap();
    let mut last_answer = 0.0;

    if let Some(input) = cli.input {
