#[derive(Debug, PartialEq, Clone)]
enum Token {
    Number(f64),
    Identifier(String),
    Plus,
    Minus,
    Mul,
    Div,
    Pow,
    Comma,
    OpenParen,
    CloseParen,
    Underscore,
}

fn tokenize(input: &str) -> Vec<Token> {
    let input = input.replace(" ", "");
    let mut tokens = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '+' => tokens.push(Token::Plus),
            '-' => tokens.push(Token::Minus),
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    tokens.push(Token::Pow);
                    i += 1;
                } else {
                    tokens.push(Token::Mul);
                }
            }
            '/' => tokens.push(Token::Div),
            '^' => tokens.push(Token::Pow),
            ',' => tokens.push(Token::Comma),
            '(' => tokens.push(Token::OpenParen),
            ')' => tokens.push(Token::CloseParen),
            '_' => tokens.push(Token::Underscore),
            '0'..='9' | '.' => {
                let mut s = String::new();
                while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    s.push(chars[i]);
                    i += 1;
                }
                if let Ok(n) = s.parse::<f64>() {
                    tokens.push(Token::Number(n));
                }
                continue;
            }
            'a'..='z' | 'A'..='Z' => {
                let mut s = String::new();
                while i < chars.len() && chars[i].is_ascii_alphabetic() {
                    s.push(chars[i]);
                    i += 1;
                }
                tokens.push(Token::Identifier(s));
                continue;
            }
            _ => {}
        }
        i += 1;
    }
    tokens
}

fn apply_implicit_multiplication(tokens: Vec<Token>) -> Vec<Token> {
    if tokens.is_empty() { return tokens; }
    let mut result = Vec::new();
    for i in 0..tokens.len() {
        result.push(tokens[i].clone());
        if i + 1 < tokens.len() {
            let curr = &tokens[i];
            let next = &tokens[i + 1];

            let mut insert_mul = false;
            match (curr, next) {
                (Token::Number(_), Token::OpenParen) => insert_mul = true,
                (Token::Number(_), Token::Identifier(_)) => insert_mul = true,
                (Token::Number(_), Token::Underscore) => insert_mul = true,
                (Token::CloseParen, Token::OpenParen) => insert_mul = true,
                (Token::Identifier(_), Token::Number(_)) => insert_mul = true,
                (Token::Underscore, Token::Number(_)) => insert_mul = true,
                (Token::Underscore, Token::Identifier(_)) => insert_mul = true,
                (Token::Identifier(_), Token::Underscore) => insert_mul = true,
                (Token::Underscore, Token::Underscore) => insert_mul = true,
                // Constant followed by open paren is a function call, NOT implicit mul
                _ => {}
            }
            if insert_mul {
                result.push(Token::Mul);
            }
        }
    }
    result
}

