struct ParserState {
    tokens: Vec<Token>,
    pos: usize,
    last_answer: f64,
    unit: AngleUnit,
}

impl ParserState {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn next(&mut self) -> Option<Token> {
        let t = self.tokens.get(self.pos).cloned();
        if t.is_some() {
            self.pos += 1;
        }
        t
    }

    fn parse_expression(&mut self) -> Result<f64, String> {
        let mut val = self.parse_term()?;
        while let Some(t) = self.peek() {
            match t {
                Token::Plus => {
                    self.next();
                    val += self.parse_term()?;
                }
                Token::Minus => {
                    self.next();
                    val -= self.parse_term()?;
                }
                _ => break,
            }
        }
        Ok(val)
    }

    fn parse_term(&mut self) -> Result<f64, String> {
        let mut val = self.parse_factor()?;
        while let Some(t) = self.peek() {
            match t {
                Token::Mul => {
                    self.next();
                    val *= self.parse_factor()?;
                }
                Token::Div => {
                    self.next();
                    val /= self.parse_factor()?;
                }
                _ => break,
            }
        }
        Ok(val)
    }

    fn parse_factor(&mut self) -> Result<f64, String> {
        let mut val = self.parse_unary()?;
        if let Some(Token::Pow) = self.peek() {
            self.next();
            val = val.powf(self.parse_factor()?);
        }
        Ok(val)
    }

    fn parse_unary(&mut self) -> Result<f64, String> {
        match self.peek() {
            Some(Token::Plus) => {
                self.next();
                self.parse_unary()
            }
            Some(Token::Minus) => {
                self.next();
                Ok(-self.parse_unary()?)
            }
            _ => self.parse_primary(),
        }
    }

    fn parse_primary(&mut self) -> Result<f64, String> {
        match self.next() {
            Some(Token::Number(n)) => Ok(n),
            Some(Token::Underscore) => Ok(self.last_answer),
            Some(Token::Identifier(s)) => {
                if let Some(Token::OpenParen) = self.peek() {
                    self.next(); // consume '('
                    let mut args = Vec::new();
                    if let Some(Token::CloseParen) = self.peek() {
                        self.next();
                    } else {
                        args.push(self.parse_expression()?);
                        while let Some(Token::Comma) = self.peek() {
                            self.next();
                            args.push(self.parse_expression()?);
                        }
                        if let Some(Token::CloseParen) = self.peek() {
                            self.next();
                        }
                        // else auto-balance
                    }
                    self.call_function(&s, args)
                } else {
                    self.get_constant(&s)
                }
            }
            Some(Token::OpenParen) => {
                let val = self.parse_expression()?;
                if let Some(Token::CloseParen) = self.peek() {
                    self.next();
                }
                // else auto-balance
                Ok(val)
            }
            _ => Err("Parser Error: Too many operators, too few operands".to_string()),
        }
    }

    fn get_constant(&self, s: &str) -> Result<f64, String> {
        match s {
            "pi" => Ok(std::f64::consts::PI),
            "e" => Ok(std::f64::consts::E),
            _ => Err("Parser Error: Too many operators, too few operands".to_string()),
        }
    }

    fn call_function(&self, s: &str, args: Vec<f64>) -> Result<f64, String> {
        let to_rad = match self.unit {
            AngleUnit::degree => std::f64::consts::PI / 180.0,
            AngleUnit::radian => 1.0,
            AngleUnit::gradian => std::f64::consts::PI / 180.0, // Should be 180? No, 200. But binary ignores it.
        };

        match s {
            "sin" => Ok(args[0].to_radians_custom(to_rad).sin()),
            "cos" => Ok(args[0].to_radians_custom(to_rad).cos()),
            "tan" => Ok(args[0].to_radians_custom(to_rad).tan()),
            "csc" => Ok(1.0 / args[0].to_radians_custom(to_rad).sin()),
            "sec" => Ok(1.0 / args[0].to_radians_custom(to_rad).cos()),
            "cot" => Ok(1.0 / args[0].to_radians_custom(to_rad).tan()),
            "sinh" => Ok(args[0].sinh()),
            "cosh" => Ok(args[0].cosh()),
            "tanh" => Ok(args[0].tanh()),
            "asin" => Ok(args[0].asin() / to_rad),
            "acos" => Ok(args[0].acos() / to_rad),
            "atan" => Ok(args[0].atan() / to_rad),
            "acsc" => Ok((1.0 / args[0]).asin() / to_rad),
            "asec" => Ok((1.0 / args[0]).acos() / to_rad),
            "acot" => Ok((1.0 / args[0]).atan() / to_rad),
            "ln" => Ok(args[0].ln()),
            "log2" => Ok(args[0].log2()),
            "log10" => Ok(args[0].log10()),
            "sqrt" => Ok(args[0].sqrt()),
            "ceil" => Ok(args[0].ceil()),
            "floor" => Ok(args[0].floor()),
            "abs" => Ok(args[0].abs()),
            "log" => {
                if args.len() < 2 { return Err("Parser Error: To few arguments for function, need 2".to_string()); }
                Ok(args[0].log(args[1]))
            }
            "nroot" => {
                if args.len() < 2 { return Err("Parser Error: To few arguments for function, need 2".to_string()); }
                Ok(args[0].powf(1.0 / args[1]))
            }
            _ => Err(format!("Syntax Error: Unknown function '{}'", s)),
        }
    }
}

trait ToRad {
    fn to_radians_custom(&self, factor: f64) -> f64;
}
impl ToRad for f64 {
    fn to_radians_custom(&self, factor: f64) -> f64 {
        self * factor
    }
}

fn format_result(value: f64, radix: u32, precision: usize) -> String {
    if radix == 10 {
        let s = format!("{:.*}", precision, value);
        let parts: Vec<&str> = s.split('.').collect();
        let integer = parts[0];
        let mut result = String::new();
        let mut count = 0;
        let is_negative = integer.starts_with('-');
        let digits = if is_negative { &integer[1..] } else { integer };
        for c in digits.chars().rev() {
            if count > 0 && count % 3 == 0 {
                result.push(',');
            }
            result.push(c);
            count += 1;
        }
        if is_negative {
            result.push('-');
        }
        let mut res: String = result.chars().rev().collect();
        if parts.len() > 1 {
            res.push('.');
            res.push_str(parts[1]);
        }
        res
    } else {
        format_other_base(value, radix, precision)
    }
}

fn format_other_base(value: f64, radix: u32, precision: usize) -> String {
    let is_negative = value < 0.0;
    let val = value.abs();
    let mut integer = val.floor() as u64;
    let mut frac = val - val.floor();

    let mut int_str = String::new();
    if integer == 0 {
        int_str.push('0');
    } else {
        while integer > 0 {
            let digit = (integer % radix as u64) as u32;
            int_str.push(std::char::from_digit(digit, radix).unwrap().to_ascii_uppercase());
            integer /= radix as u64;
        }
    }
    if is_negative {
        int_str.push('-');
    }

    // Grouping by 3 from right
    let mut grouped_int = String::new();
    let mut count = 0;
    for c in int_str.chars() { // int_str is already reversed
        if count > 0 && count % 3 == 0 {
            grouped_int.push(',');
        }
        grouped_int.push(c);
        count += 1;
    }

    let mut res_int: String = grouped_int.chars().rev().collect();

    // Pad with groups to reach at least 4 groups
    // Total groups = (count + 2) / 3
    let mut groups = (count + 2) / 3;
    while groups < 4 {
        res_int.insert(0, ',');
        res_int.insert(0, ' ');
        res_int.insert(0, ' ');
        res_int.insert(0, ' ');
        groups += 1;
    }
    // Remove the leading comma if it was added as padding
    if res_int.starts_with(',') {
        // This shouldn't happen with the "   ," logic
    }
    // Wait, my padding logic is slightly wrong.
    // Let's re-calculate.

    // Re-implementation of other base formatting:
    let mut int_digits = Vec::new();
    let mut temp_int = val.floor() as u64;
    if temp_int == 0 {
        int_digits.push('0');
    } else {
        while temp_int > 0 {
            let d = (temp_int % radix as u64) as u32;
            int_digits.push(std::char::from_digit(d, radix).unwrap().to_ascii_uppercase());
            temp_int /= radix as u64;
        }
    }
    if is_negative {
        int_digits.push('-');
    }

    let mut groups = Vec::new();
    let mut current_group = String::new();
    for i in 0..int_digits.len() {
        if i > 0 && i % 3 == 0 {
            groups.push(current_group.chars().rev().collect::<String>());
            current_group = String::new();
        }
        current_group.push(int_digits[i]);
    }
    groups.push(current_group.chars().rev().collect::<String>());

    while groups.len() < 4 {
        groups.push("   ".to_string());
    }

    let mut res = groups.iter().rev().cloned().collect::<Vec<String>>().join(",");

    // Fraction
    if precision > 0 {
        let mut frac_str = String::new();
        for _ in 0..precision {
            frac *= radix as f64;
            let digit = frac.floor() as u32;
            frac_str.push(std::char::from_digit(digit, radix).unwrap().to_ascii_uppercase());
            frac -= frac.floor();
        }
        // Strip trailing zeros
        let stripped = frac_str.trim_end_matches('0');
        if stripped.is_empty() {
            res.push_str(".0");
        } else {
            res.push('.');
            res.push_str(stripped);
        }
    } else {
        res.push_str(".0");
    }

    res
}
