struct ParserState {
    tokens: Vec<Token>,
    pos: usize,
    last_answer: f64,
    unit: AngleUnit,
}

impl ParserState {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn next(&mut self) -> Option<Token> {
        let t = self.tokens.get(self.pos).cloned();
        if t.is_some() {
            self.pos += 1;
        }
        t
    }

    fn parse_expression(&mut self) -> Result<f64, String> {
        let mut val = self.parse_term()?;
        while let Some(t) = self.peek() {
            match t {
                Token::Plus => {
                    self.next();
                    val += self.parse_term()?;
                }
                Token::Minus => {
                    self.next();
                    val -= self.parse_term()?;
                }
                _ => break,
            }
        }
        Ok(val)
    }

    fn parse_term(&mut self) -> Result<f64, String> {
        let mut val = self.parse_factor()?;
        while let Some(t) = self.peek() {
            match t {
                Token::Mul => {
                    self.next();
                    val *= self.parse_factor()?;
                }
                Token::Div => {
                    self.next();
                    val /= self.parse_factor()?;
                }
                _ => break,
            }
        }
        Ok(val)
    }

    fn parse_factor(&mut self) -> Result<f64, String> {
        let mut val = self.parse_unary()?;
        if let Some(Token::Pow) = self.peek() {
            self.next();
            val = val.powf(self.parse_factor()?);
        }
        Ok(val)
    }

    fn parse_unary(&mut self) -> Result<f64, String> {
        match self.peek() {
            Some(Token::Plus) => {
                self.next();
                self.parse_unary()
            }
            Some(Token::Minus) => {
                self.next();
                Ok(-self.parse_unary()?)
            }
            _ => self.parse_primary(),
        }
    }

    fn parse_primary(&mut self) -> Result<f64, String> {
        match self.next() {
            Some(Token::Number(n)) => Ok(n),
            Some(Token::Underscore) => Ok(self.last_answer),
            Some(Token::Identifier(s)) => {
                if let Some(Token::OpenParen) = self.peek() {
                    self.next();
                    let mut args = Vec::new();
                    if let Some(Token::CloseParen) = self.peek() {
                        self.next();
                    } else {
                        args.push(self.parse_expression()?);
                        while let Some(Token::Comma) = self.peek() {
                            self.next();
                            args.push(self.parse_expression()?);
                        }
                        if let Some(Token::CloseParen) = self.peek() {
                            self.next();
                        }
                    }
                    self.call_function(&s, args)
                } else {
                    self.get_constant(&s)
                }
            }
            Some(Token::OpenParen) => {
                let val = self.parse_expression()?;
                if let Some(Token::CloseParen) = self.peek() {
                    self.next();
                }
                Ok(val)
            }
            _ => Err("Parser Error: Too many operators, too few operands".to_string()),
        }
    }

    fn get_constant(&self, s: &str) -> Result<f64, String> {
        match s {
            "pi" => Ok(std::f64::consts::PI),
            "e" => Ok(std::f64::consts::E),
            _ => Err("Parser Error: Too many operators, too few operands".to_string()),
        }
    }

    fn call_function(&self, s: &str, args: Vec<f64>) -> Result<f64, String> {
        let to_rad = match self.unit {
            AngleUnit::Degree => std::f64::consts::PI / 180.0,
            AngleUnit::Radian => 1.0,
            AngleUnit::Gradian => std::f64::consts::PI / 180.0,
        };

        if s == "log" || s == "nroot" {
            if args.len() < 2 {
                return Err("Parser Error: To few arguments for function, need 2".to_string());
            }
        } else if args.is_empty() {
             // Handled by 1-arg functions
        }

        match s {
            "sin" => Ok(args[0].to_radians_custom(to_rad).sin()),
            "cos" => Ok(args[0].to_radians_custom(to_rad).cos()),
            "tan" => Ok(args[0].to_radians_custom(to_rad).tan()),
            "csc" => Ok(1.0 / args[0].to_radians_custom(to_rad).sin()),
            "sec" => Ok(1.0 / args[0].to_radians_custom(to_rad).cos()),
            "cot" => Ok(1.0 / args[0].to_radians_custom(to_rad).tan()),
            "sinh" => Ok(args[0].sinh()),
            "cosh" => Ok(args[0].cosh()),
            "tanh" => Ok(args[0].tanh()),
            "asin" => Ok(args[0].asin() / to_rad),
            "acos" => Ok(args[0].acos() / to_rad),
            "atan" => Ok(args[0].atan() / to_rad),
            "acsc" => Ok((1.0 / args[0]).asin() / to_rad),
            "asec" => Ok((1.0 / args[0]).acos() / to_rad),
            "acot" => Ok((1.0 / args[0]).atan() / to_rad),
            "ln" => Ok(args[0].ln()),
            "log2" => Ok(args[0].log2()),
            "log10" => Ok(args[0].log10()),
            "sqrt" => Ok(args[0].sqrt()),
            "ceil" => Ok(args[0].ceil()),
            "floor" => Ok(args[0].floor()),
            "abs" => Ok(args[0].abs()),
            "log" => Ok(args[0].log(args[1])),
            "nroot" => Ok(args[0].powf(1.0 / args[1])),
            _ => Err(format!("Syntax Error: Unknown function '{}'", s)),
        }
    }
}

trait ToRad {
    fn to_radians_custom(&self, factor: f64) -> f64;
}
impl ToRad for f64 {
    fn to_radians_custom(&self, factor: f64) -> f64 {
        self * factor
    }
}

fn format_result(value: f64, radix: u32, precision: usize) -> String {
    if radix == 10 {
        let s = format!("{:.*}", precision, value);
        let parts: Vec<&str> = s.split('.').collect();
        let integer = parts[0];
        let mut result = String::new();
        let mut count = 0;
        let is_negative = integer.starts_with('-');
