enum class TokenType {
    Number, Identifier, Plus, Minus, Mul, Div, Pow, Comma, OpenParen, CloseParen, Underscore, End
};

struct Token {
    TokenType type;
    string value;
    double num;
};

vector<Token> tokenize(string input) {
    // Remove spaces
    input.erase(remove(input.begin(), input.end(), ' '), input.end());

    vector<Token> tokens;
    for (size_t i = 0; i < input.length(); ++i) {
        if (isdigit(input[i]) || input[i] == '.') {
            string s;
            while (i < input.length() && (isdigit(input[i]) || input[i] == '.')) {
                s += input[i++];
            }
            tokens.push_back({TokenType::Number, s, stod(s)});
            i--;
        } else if (isalpha(input[i])) {
            string s;
            while (i < input.length() && isalpha(input[i])) {
                s += input[i++];
            }
            tokens.push_back({TokenType::Identifier, s, 0});
            i--;
        } else if (input[i] == '+') {
            tokens.push_back({TokenType::Plus, "+", 0});
        } else if (input[i] == '-') {
            tokens.push_back({TokenType::Minus, "-", 0});
        } else if (input[i] == '*') {
            if (i + 1 < input.length() && input[i+1] == '*') {
                tokens.push_back({TokenType::Pow, "**", 0});
                i++;
            } else {
                tokens.push_back({TokenType::Mul, "*", 0});
            }
        } else if (input[i] == '/') {
            tokens.push_back({TokenType::Div, "/", 0});
        } else if (input[i] == '^') {
            tokens.push_back({TokenType::Pow, "^", 0});
        } else if (input[i] == ',') {
            tokens.push_back({TokenType::Comma, ",", 0});
        } else if (input[i] == '(') {
            tokens.push_back({TokenType::OpenParen, "(", 0});
        } else if (input[i] == ')') {
            tokens.push_back({TokenType::CloseParen, ")", 0});
        } else if (input[i] == '_') {
            tokens.push_back({TokenType::Underscore, "_", 0});
        } else {
            // Error handling for unexpected characters
            string s;
            while (i < input.length() && isalnum(input[i])) {
                s += input[i++];
            }
            throw "Syntax Error: Unexpected character '" + s + "'";
        }
    }
    return tokens;
}

vector<Token> apply_implicit_mul(vector<Token> tokens) {
    vector<Token> result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        result.push_back(tokens[i]);
        if (i + 1 < tokens.size()) {
            TokenType curr = tokens[i].type;
            TokenType next = tokens[i+1].type;
            bool insert = false;
            if (curr == TokenType::Number && next == TokenType::OpenParen) insert = true;
            if (curr == TokenType::Number && next == TokenType::Identifier) insert = true;
            if (curr == TokenType::Number && next == TokenType::Underscore) insert = true;
            if (curr == TokenType::CloseParen && next == TokenType::OpenParen) insert = true;
            if (curr == TokenType::Identifier && next == TokenType::Number) insert = true;
            if (curr == TokenType::Underscore && next == TokenType::Number) insert = true;
            if (curr == TokenType::Underscore && next == TokenType::Identifier) insert = true;
            if (curr == TokenType::Identifier && next == TokenType::Underscore) insert = true;
            if (curr == TokenType::Underscore && next == TokenType::Underscore) insert = true;

            if (insert) {
                result.push_back({TokenType::Mul, "*", 0});
            }
        }
    }
    return result;
}

struct Parser {
    vector<Token> tokens;
    size_t pos = 0;
    double last_answer;
    string unit;

    Token peek() {
        if (pos < tokens.size()) return tokens[pos];
        return {TokenType::End, "", 0};
    }

    Token next() {
        if (pos < tokens.size()) return tokens[pos++];
        return {TokenType::End, "", 0};
    }

    double parse_expression() {
        double val = parse_term();
        while (peek().type == TokenType::Plus || peek().type == TokenType::Minus) {
            Token t = next();
            if (t.type == TokenType::Plus) val += parse_term();
            else val -= parse_term();
        }
        return val;
    }

    double parse_term() {
        double val = parse_factor();
        while (peek().type == TokenType::Mul || peek().type == TokenType::Div) {
            Token t = next();
            if (t.type == TokenType::Mul) val *= parse_factor();
            else val /= parse_factor();
        }
        return val;
    }

    double parse_factor() {
        double val = parse_unary();
        if (peek().type == TokenType::Pow) {
            next();
            val = pow(val, parse_factor());
        }
        return val;
    }

    double parse_unary() {
        if (peek().type == TokenType::Plus) {
            next();
            return parse_unary();
        }
        if (peek().type == TokenType::Minus) {
            next();
            return -parse_unary();
        }
        return parse_primary();
    }

    double parse_primary() {
        Token t = next();
        if (t.type == TokenType::Number) return t.num;
        if (t.type == TokenType::Underscore) return last_answer;
        if (t.type == TokenType::Identifier) {
            if (peek().type == TokenType::OpenParen) {
                next();
                vector<double> args;
                if (peek().type != TokenType::CloseParen) {
                    args.push_back(parse_expression());
                    while (peek().type == TokenType::Comma) {
                        next();
                        args.push_back(parse_expression());
                    }
                }
                if (peek().type == TokenType::CloseParen) next();
                return call_function(t.value, args);
            } else {
                return get_constant(t.value);
            }
        }
        if (t.type == TokenType::OpenParen) {
            double val = parse_expression();
            if (peek().type == TokenType::CloseParen) next();
            return val;
        }
        throw string("Parser Error: Too many operators, too few operands");
    }

    double get_constant(string s) {
        if (s == "pi") return M_PI;
        if (s == "e") return M_E;
        throw string("Parser Error: Too many operators, too few operands");
    }

    double call_function(string s, vector<double> args) {
        double to_rad = (unit == "radian") ? 1.0 : M_PI / 180.0;

        if (s == "log" || s == "nroot") {
            if (args.size() < 2) throw string("Parser Error: To few arguments for function, need 2");
        } else {
            if (args.size() < 1) throw string("Parser Error: Too many operators, too few operands");
        }

        if (s == "sin") return sin(args[0] * to_rad);
        if (s == "cos") return cos(args[0] * to_rad);
        if (s == "tan") return tan(args[0] * to_rad);
        if (s == "csc") return 1.0 / sin(args[0] * to_rad);
        if (s == "sec") return 1.0 / cos(args[0] * to_rad);
        if (s == "cot") return 1.0 / tan(args[0] * to_rad);
        if (s == "sinh") return sinh(args[0]);
        if (s == "cosh") return cosh(args[0]);
        if (s == "tanh") return tanh(args[0]);
        if (s == "asin") return asin(args[0]) / to_rad;
        if (s == "acos") return acos(args[0]) / to_rad;
        if (s == "atan") return atan(args[0]) / to_rad;
        if (s == "acsc") return asin(1.0 / args[0]) / to_rad;
        if (s == "asec") return acos(1.0 / args[0]) / to_rad;
        if (s == "acot") return atan(1.0 / args[0]) / to_rad;
        if (s == "ln") return log(args[0]);
        if (s == "log2") return log2(args[0]);
        if (s == "log10") return log10(args[0]);
        if (s == "sqrt") return sqrt(args[0]);
        if (s == "ceil") return ceil(args[0]);
        if (s == "floor") return floor(args[0]);
        if (s == "abs") return abs(args[0]);
        if (s == "log") return log(args[0]) / log(args[1]);
        if (s == "nroot") return pow(args[0], 1.0 / args[1]);

        throw "Syntax Error: Unknown function '" + s + "'";
    }
};

string format_result(double value, int base, int fix) {
    if (base == 10) {
        char buf[256];
        sprintf(buf, "%.*f", fix, value);
        string s = buf;
        size_t dot = s.find('.');
        string integer = s.substr(0, dot);
        string fractional = (dot != string::npos) ? s.substr(dot) : "";

        string result;
        int count = 0;
        bool neg = (integer[0] == '-');
        string digits = neg ? integer.substr(1) : integer;
        for (int i = digits.length() - 1; i >= 0; --i) {
            if (count > 0 && count % 3 == 0) result += ',';
            result += digits[i];
            count++;
        }
        if (neg) result += '-';
        reverse(result.begin(), result.end());
        return result + fractional;
    } else {
        bool neg = (value < 0);
        value = abs(value);
        unsigned long long int_part = (unsigned long long)floor(value);
        double frac_part = value - floor(value);

        vector<char> digits;
        if (int_part == 0) digits.push_back('0');
        else {
            while (int_part > 0) {
                int d = int_part % base;
                digits.push_back(d < 10 ? d + '0' : d - 10 + 'A');
                int_part /= base;
            }
        }
        if (neg) digits.push_back('-');

        vector<string> groups;
        string cur;
        for (size_t i = 0; i < digits.size(); ++i) {
            cur += digits[i];
            if ((i + 1) % 3 == 0 || i + 1 == digits.size()) {
                reverse(cur.begin(), cur.end());
                groups.push_back(cur);
                cur = "";
            }
        }
        while (groups.size() < 4) groups.push_back("   ");

        string res;
        for (int i = groups.size() - 1; i >= 0; --i) {
            res += groups[i];
            if (i > 0) res += ',';
        }

        string frac_str = ".";
        for (int i = 0; i < fix; ++i) {
            frac_part *= base;
            int d = (int)floor(frac_part);
            frac_str += (d < 10 ? d + '0' : d - 10 + 'A');
            frac_part -= d;
        }
        while (frac_str.length() > 2 && frac_str.back() == '0') frac_str.pop_back();
        if (frac_str == ".") frac_str = ".0";

        return res + frac_str;
    }
}

int main(int argc, char** argv) {
    int fix = 10;
    int base = 10;
    string unit = "degree";
    string input = "";

    for (int i = 1; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-f" || arg == "--fix") {
            fix = stoi(argv[++i]);
        } else if (arg == "-b" || arg == "--base") {
            base = stoi(argv[++i]);
        } else if (arg == "-a" || arg == "--angle_unit") {
            unit = argv[++i];
        } else if (arg == "-h" || arg == "--help") {
            cout << "Calculator REPL similar to bc(1)" << endl << endl;
            cout << "Usage: executable [OPTIONS] [INPUT]" << endl << endl;
            cout << "Arguments:" << endl;
            cout << "  [INPUT]  Optional expression string to run eva in command mode" << endl << endl;
            cout << "Options:" << endl;
            cout << "  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]" << endl;
            cout << "  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]" << endl;
            cout << "  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]" << endl;
            cout << "  -h, --help                     Print help" << endl;
            cout << "  -V, --version                  Print version" << endl;
            return 0;
        } else if (arg == "-V" || arg == "--version") {
            cout << "eva 0.3.1" << endl;
            return 0;
        } else {
            input = arg;
        }
    }

    double last_answer = 0;
    bool has_history = false;

    if (!input.empty()) {
        try {
            auto tokens = tokenize(input);
            tokens = apply_implicit_mul(tokens);
            Parser p = {tokens, 0, last_answer, unit};
            double res = p.parse_expression();
            if (p.pos < tokens.size()) throw string("Parser Error: Too many operators, too few operands");
            cout << format_result(res, base, fix) << endl;
        } catch (string e) {
            cerr << e << endl;
            return 1;
        } catch (const char* e) {
            cerr << e << endl;
            return 1;
        }
    } else {
        string line;
        while (true) {
            cout << "> ";
            if (!getline(cin, line)) break;
            if (line.empty()) continue;

            try {
                if (line.find('_') != string::npos && !has_history) {
                    cout << "No previous history." << endl;
                }
                auto tokens = tokenize(line);
                tokens = apply_implicit_mul(tokens);
                Parser p = {tokens, 0, last_answer, unit};
                double res = p.parse_expression();
                if (p.pos < tokens.size()) throw string("Parser Error: Too many operators, too few operands");
                cout << format_result(res, base, fix) << endl;
                last_answer = res;
                has_history = true;
            } catch (string e) {
                cerr << e << endl;
            } catch (const char* e) {
                cerr << e << endl;
            }
        }
    }

    return 0;
}
